N_LIST = [2, 3, 4, 6]
TARGET_NAMES = ["GHZ", "W", "TFI h=0.5", "TFI h=1", "TFI h=2", "non-integrable"]
H_TFI = {"TFI h=0.5": 0.5, "TFI h=1": 1.0, "TFI h=2": 2.0}
J_KH, H_KH, G_KH = -1.0, -(5 + np.sqrt(5)) / 8, -(1 + np.sqrt(5)) / 4      # Kim-Huse bulk point in our convention

def ising_terms(N, J, h, g):
    # H = -J sum Z_i Z_{i+1} - h sum X_i - g sum Z_i on an open chain, as local terms of the engine
    return heisenberg_terms(N, Jxx=0.0, Jyy=0.0, Jzz=-J, hx=-h, hz=-g)

def tfi_ground_state(N, h, m=80):
    # Lanczos from |+...+>: the iteration stays in the sector symmetric under prod_i X_i
    terms = ising_terms(N, J=1.0, h=h, g=0.0)
    start = jnp.ones((2,) * N, dtype=CDTYPE) / 2 ** (N / 2)
    a, b, V = lanczos(jax.jit(lambda p: apply_hamiltonian(terms, p)), start, min(m, 2 ** N))
    w, vecs = np.linalg.eigh(np.diag(a) + np.diag(b, 1) + np.diag(b, -1))
    psi = jnp.tensordot(jnp.asarray(vecs[:, 0], dtype=CDTYPE), V, axes=1)
    return terms, psi / jnp.linalg.norm(psi)

def build_targets(N):
    out, hams = {"GHZ": ghz_state(N), "W": w_state(N)}, {}
    for name, h in H_TFI.items():
        hams[name], out[name] = tfi_ground_state(N, h)
    hams["non-integrable"] = ising_terms(N, J=J_KH, h=H_KH, g=G_KH)
    out["non-integrable"] = lanczos_ground_state(hams["non-integrable"], N, m=min(80, 2 ** N))[1]
    return out, hams

TARGETS, S_HALF = {}, {}
