    TARGETS[N] = tg
    for name, terms in hams.items():                     # check against exact diagonalisation (float64)
        E, V = np.linalg.eigh(np.asarray(dense_hamiltonian(terms, N), dtype=np.complex128))
        e_lz = float(jnp.real(jnp.vdot(tg[name], apply_hamiltonian(terms, tg[name]))))
        # the projector onto the lowest level, or onto the lowest two when they are nearly degenerate
        k = 2 if E[1] - E[0] < 1e-3 else 1
        overlap = np.sum(np.abs(V[:, :k].conj().T @ np.asarray(tg[name]).reshape(-1)) ** 2)
        assert abs(e_lz - E[0]) < 1e-3 and overlap > 0.999, (N, name, e_lz, E[0], overlap)
    S_HALF[N] = {n: float(entanglement_entropy(v, tuple(range(N // 2)))) for n, v in tg.items()}
    F0 = {n: float(fidelity_pure(v, zero_state(N))) for n, v in tg.items()}
