ZETA_CX = 0.03                                             # cost of one CNOT, single-qubit gates keep ZETA = 0.01

def cost_vector(env, zeta=ZETA, zeta_cx=ZETA_CX):
    # one cost per gate of the gate set: zeta for H, S, T and zeta_cx for every CNOT
    return jnp.array([zeta_cx if g.startswith("CX") else zeta for g in env["gate_names"]])

def n_cnot(gates):
    return sum(g.startswith("CX") for g in gates)

def run_circuit(N, gates):
    # the state prepared from |0...0> by a list of gate names
    lookup = {g: (U, q) for g, U, q in gate_set(N)}
    psi = zero_state(N)
    for g in gates:
        psi = apply_gate(psi, *lookup[g])
    return psi

def count_sequences(N, target, L):
    # number of gate sequences of exactly L gates that reach F > 0.99 at the last gate and not before, by CNOT count
    gates = gate_set(N); is_cx = [g.startswith("CX") for g, _, _ in gates]
    all_next = jax.jit(jax.vmap(lambda p: jnp.stack([apply_gate(p, U, q) for _, U, q in gates])))
    def key(v):
        k = np.argmax(np.abs(v) > 1e-4); c = v * (abs(v[k]) / v[k])
        return (np.round(np.r_[c.real, c.imag], 4).astype(np.float32) + 0.0).tobytes()
    tg = np.asarray(target).reshape(-1)
    v0 = np.asarray(zero_state(N)).reshape(-1)
    layer = {key(v0): (v0, {0: 1})}                       # state -> (vector, {CNOT count: number of sequences})
    for d in range(L):
        keys = list(layer)
        nxt = np.asarray(all_next(jnp.asarray(np.stack([layer[k][0] for k in keys]).reshape((-1,) + (2,) * N))))
        new = {}
        for i, k in enumerate(keys):
            for a, v in enumerate(nxt[i].reshape(len(gates), -1)):
                if abs(np.vdot(tg, v)) ** 2 > F_SUCCESS and d < L - 1:
                    continue                               # this episode would have ended at an earlier gate
                vec, counts = new.setdefault(key(v), (v, {}))
                for c, m in layer[k][1].items():
                    counts[c + is_cx[a]] = counts.get(c + is_cx[a], 0) + m
        layer = new
    hits = {}
    for v, counts in layer.values():
        if abs(np.vdot(tg, v)) ** 2 > F_SUCCESS:
            for c, m in counts.items():
                hits[int(c)] = hits.get(int(c), 0) + m
    return dict(sorted(hits.items()))

