def circuit_return(N, target, gates, cost):
    # discounted return of a fixed circuit; the episode ends at the first gate with F > 0.99
    env = make_env(N); psi, G = env["psi0"], 0.0
    for t, g in enumerate(gates):
        psi, r, done = env["step"](psi, env["gate_names"].index(g), target, False, jnp.asarray(cost))
        G += GAMMA ** t * float(r)
        if bool(done):
            break
    return G

